/// What breaking a block with a plain tool can drop; empty when nothing does.
pub fn drops_of(block: BlockKind) -> &'static [Drop] {
    BLOCK_DROPS
        .binary_search_by_key(&block.id(), |d| d.block.id())
        .ok()
        .and_then(|i| BLOCK_DROPS.get(i))
        .map_or(&[], |d| d.tries)
}
